def decimal_to_binary(n):
    """Converts a non-negative integer to its binary representation wrapped with 'db' prefix and suffix.
    Returns the string in format 'db<binary>db'. Raises ValueError for invalid input."""
    if not isinstance(n, int):
        raise ValueError("Input must be a non-negative integer")
    if n < 0:
        raise ValueError("Input must be non-negative")
    binary_str = bin(n)[2:]
    return f"db{binary_str}db"

